  "classification": "packaging_error",
  "confidence": 0.9,
  "solution": "Android APK packaging and signing failure. Solution: 1) Verify Android SDK path in Project Settings 2) Check keystore configuration 3) Ensure Target SDK is set to 32 for Quest 4) Clean intermediate files 5) Regenerate signing certificate if needed 6) Check available disk space",
  "metadata": {
    "severity": "high",
    "platform": "android",
    "category": "build"
  }
}

{
  "classification": "plugin_conflict",
  "confidence": 0.95,
  "solution": "XR plugin conflict between MetaXR and OculusXR. Solution: 1) Go to Edit \u2192 Plugins 2) Disable OculusXR plugin if using MetaXR 3) Only enable one XR plugin at a time 4) Restart Unreal Editor 5) Regenerate project files 6) Verify plugin dependencies",
  "metadata": {
    "severity": "critical",
    "platform": "quest",
    "category": "plugins"
  }
}
